/* Functions to access TPS65215/TPS65219 Power Management Integrated Chips */

// C header dependencies: linux/bitops.h, linux/regmap.h, linux/regulator/driver.h
const fn bit(n: u32) -> u32 { 1u32 << n }
const fn genmask(hi: u32, lo: u32) -> u32 { ((1u32 << (hi - lo + 1)) - 1) << lo }

